/**
 * Tree Row Extractor
 *
 * Extracts individual trees from horizontal row arrangements generated by Gemini.
 * Improved algorithm that:
 * - Detects white gaps between trees to find column boundaries
 * - Extracts each tree with proper cropping
 * - Validates each tree is complete (not cut off)
 * - Prevents duplicate/merged trees
 *
 * Usage: node scripts/extract-tree-row.cjs <input-image> <category> [output-dir]
 * Example: node scripts/extract-tree-row.cjs "C:/Users/Austen/Downloads/dead-trees.png" dead
 */

const { createCanvas, loadImage } = require('canvas');
const fs = require('fs');
const path = require('path');

const DEFAULT_OUTPUT_DIR = 'static/images/trees/extracted';

async function extractTreesFromRow(inputPath, category, outputDir = DEFAULT_OUTPUT_DIR) {
  console.log(`\nExtracting ${category} trees from: ${inputPath}`);

  // Load the image
  const img = await loadImage(inputPath);
  const width = img.width;
  const height = img.height;

  console.log(`Image size: ${width}x${height}`);

  // Create canvas and get pixel data
  const canvas = createCanvas(width, height);
  const ctx = canvas.getContext('2d');
  ctx.drawImage(img, 0, 0);
  const imageData = ctx.getImageData(0, 0, width, height);
  const pixels = imageData.data;

  // Helper to check if a pixel is "white" (background)
  function isWhite(x, y) {
    if (x < 0 || x >= width || y < 0 || y >= height) return true;
    const idx = (y * width + x) * 4;
    const r = pixels[idx];
    const g = pixels[idx + 1];
    const b = pixels[idx + 2];
    // Consider near-white as white (threshold 240)
    return r > 240 && g > 240 && b > 240;
  }

  // Helper to check if a pixel is "black" (tree)
  function isBlack(x, y) {
    if (x < 0 || x >= width || y < 0 || y >= height) return false;
    const idx = (y * width + x) * 4;
    const r = pixels[idx];
    const g = pixels[idx + 1];
    const b = pixels[idx + 2];
    // Consider dark pixels as part of tree (threshold 50)
    return r < 50 && g < 50 && b < 50;
  }

  // Find vertical white gaps (columns that are mostly white)
  // These separate individual trees in a row arrangement
  function findWhiteColumns() {
    const columnBlackCounts = [];

    for (let x = 0; x < width; x++) {
      let blackCount = 0;
      for (let y = 0; y < height; y++) {
        if (isBlack(x, y)) blackCount++;
      }
      columnBlackCounts.push(blackCount);
    }

    // Find columns that are predominantly white (less than 5% black)
    const threshold = height * 0.05;
    const whiteColumns = [];

    for (let x = 0; x < width; x++) {
      if (columnBlackCounts[x] < threshold) {
        whiteColumns.push(x);
      }
    }

    return whiteColumns;
  }

  // Group consecutive white columns into gaps
  function findGaps(whiteColumns) {
    if (whiteColumns.length === 0) return [];

    const gaps = [];
    let gapStart = whiteColumns[0];
    let gapEnd = whiteColumns[0];

    for (let i = 1; i < whiteColumns.length; i++) {
      if (whiteColumns[i] === gapEnd + 1) {
        gapEnd = whiteColumns[i];
      } else {
        // Only count as a gap if it's wide enough (at least 20 pixels)
        if (gapEnd - gapStart >= 20) {
          gaps.push({ start: gapStart, end: gapEnd, center: Math.floor((gapStart + gapEnd) / 2) });
        }
        gapStart = whiteColumns[i];
        gapEnd = whiteColumns[i];
      }
    }

    // Don't forget the last gap
    if (gapEnd - gapStart >= 20) {
      gaps.push({ start: gapStart, end: gapEnd, center: Math.floor((gapStart + gapEnd) / 2) });
    }

    return gaps;
  }

  // Find tree boundaries within a column range
  function findTreeBounds(startX, endX) {
    let minX = endX, maxX = startX, minY = height, maxY = 0;
    let hasContent = false;

    for (let y = 0; y < height; y++) {
      for (let x = startX; x < endX; x++) {
        if (isBlack(x, y)) {
          hasContent = true;
          if (x < minX) minX = x;
          if (x > maxX) maxX = x;
          if (y < minY) minY = y;
          if (y > maxY) maxY = y;
        }
      }
    }

    if (!hasContent) return null;

    // Add padding
    const padding = 10;
    minX = Math.max(0, minX - padding);
    maxX = Math.min(width - 1, maxX + padding);
    minY = Math.max(0, minY - padding);
    maxY = Math.min(height - 1, maxY + padding);

    return { minX, maxX, minY, maxY, width: maxX - minX + 1, height: maxY - minY + 1 };
  }

  // Validate a tree is complete (not cut off at edges)
  function validateTree(bounds, regionStartX, regionEndX) {
    // Check if tree touches the very edge of its region (might be cut off)
    const touchesLeft = bounds.minX <= regionStartX + 5;
    const touchesRight = bounds.maxX >= regionEndX - 5;
    const touchesTop = bounds.minY <= 5;

    // If it touches edges, it might be cut off
    if (touchesTop) {
      console.log(`  Warning: Tree may be cut off at top`);
      return false;
    }

    // Check aspect ratio - trees should be taller than wide typically
    const aspectRatio = bounds.height / bounds.width;
    if (aspectRatio < 0.5) {
      console.log(`  Warning: Unusual aspect ratio ${aspectRatio.toFixed(2)} - may be multiple trees`);
      return false;
    }

    return true;
  }

  // Extract and save a single tree
  function extractTree(bounds, index) {
    const treeCanvas = createCanvas(bounds.width, bounds.height);
    const treeCtx = treeCanvas.getContext('2d');

    // Fill with white background
    treeCtx.fillStyle = 'white';
    treeCtx.fillRect(0, 0, bounds.width, bounds.height);

    // Copy tree pixels
    const sourceData = ctx.getImageData(bounds.minX, bounds.minY, bounds.width, bounds.height);
    treeCtx.putImageData(sourceData, 0, 0);

    // Ensure output directory exists
    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
    }

    // Find next available index for this category
    const existingFiles = fs.readdirSync(outputDir).filter(f => f.startsWith(`${category}_`));
    const existingNumbers = existingFiles.map(f => {
      const match = f.match(new RegExp(`${category}_(\\d+)\\.png`));
      return match ? parseInt(match[1]) : 0;
    });
    const nextNum = existingNumbers.length > 0 ? Math.max(...existingNumbers) + 1 : 1;
    const actualIndex = nextNum + index - 1;

    const filename = `${category}_${String(actualIndex).padStart(2, '0')}.png`;
    const outputPath = path.join(outputDir, filename);

    const buffer = treeCanvas.toBuffer('image/png');
    fs.writeFileSync(outputPath, buffer);

    console.log(`  Saved: ${filename} (${bounds.width}x${bounds.height})`);
    return filename;
  }

  // Main extraction logic
  console.log('\nAnalyzing image for tree boundaries...');

  const whiteColumns = findWhiteColumns();
  console.log(`Found ${whiteColumns.length} predominantly white columns`);

  const gaps = findGaps(whiteColumns);
  console.log(`Found ${gaps.length} gaps between potential trees`);

  // Define tree regions based on gaps
  const regions = [];

  // Add region from start to first gap
  if (gaps.length > 0) {
    regions.push({ start: 0, end: gaps[0].center });

    // Add regions between gaps
    for (let i = 0; i < gaps.length - 1; i++) {
      regions.push({ start: gaps[i].center, end: gaps[i + 1].center });
    }

    // Add region from last gap to end
    regions.push({ start: gaps[gaps.length - 1].center, end: width });
  } else {
    // No gaps found - treat entire image as one region
    regions.push({ start: 0, end: width });
  }

  console.log(`\nProcessing ${regions.length} potential tree regions...`);

  const extractedTrees = [];

  for (let i = 0; i < regions.length; i++) {
    const region = regions[i];
    console.log(`\nRegion ${i + 1}: columns ${region.start}-${region.end}`);

    const bounds = findTreeBounds(region.start, region.end);

    if (!bounds) {
      console.log(`  No tree content found, skipping`);
      continue;
    }

    console.log(`  Tree bounds: (${bounds.minX},${bounds.minY}) to (${bounds.maxX},${bounds.maxY})`);

    const isValid = validateTree(bounds, region.start, region.end);

    if (isValid) {
      const filename = extractTree(bounds, extractedTrees.length + 1);
      extractedTrees.push(filename);
    } else {
      console.log(`  Skipping invalid tree`);
    }
  }

  console.log(`\n✓ Extracted ${extractedTrees.length} trees to ${outputDir}`);
  return extractedTrees;
}

// CLI handling
const args = process.argv.slice(2);

if (args.length < 2) {
  console.log(`
Tree Row Extractor - Extract individual trees from Gemini row images

Usage: node scripts/extract-tree-row.cjs <input-image> <category> [output-dir]

Arguments:
  input-image  Path to the source image with trees in a row
  category     Tree category: dead, maple, willow, oak, pine, fir, spruce, poplar
  output-dir   Optional output directory (default: static/images/trees/extracted)

Example:
  node scripts/extract-tree-row.cjs "C:/Downloads/dead-trees.png" dead
  node scripts/extract-tree-row.cjs "C:/Downloads/maple.jpg" maple static/images/trees/curated
`);
  process.exit(1);
}

const [inputPath, category, outputDir] = args;

const validCategories = ['dead', 'maple', 'willow', 'oak', 'pine', 'fir', 'spruce', 'poplar'];
if (!validCategories.includes(category)) {
  console.error(`Invalid category: ${category}`);
  console.error(`Valid categories: ${validCategories.join(', ')}`);
  process.exit(1);
}

if (!fs.existsSync(inputPath)) {
  console.error(`Input file not found: ${inputPath}`);
  process.exit(1);
}

extractTreesFromRow(inputPath, category, outputDir || DEFAULT_OUTPUT_DIR)
  .then(() => console.log('\nDone!'))
  .catch(err => {
    console.error('Error:', err.message);
    process.exit(1);
  });
